extends Node

@export var level: PackedScene
@export var player: PackedScene
@export var accept_button: Button
@export var dismiss_button: Button
@export var prompt: Label
@export var status: Label

var _game: Game
var _shown_offer: SteamInvite
var _joining: bool = false

func _ready() -> void:
    _update_buttons()
    _game = Game.configure(level, player).steam().boot(self)
    var startup: GameResult = _game.boot_result()
    if not startup.ok:
        status.text = startup.message
        return

    accept_button.pressed.connect(_accept_offer)
    dismiss_button.pressed.connect(_dismiss_offer)
    _game.invite_changed.connect(_show_offer)
    _show_offer(_game.pending_invite())

func _show_offer(offer: SteamInvite) -> void:
    _shown_offer = offer
    prompt.text = "Join %s's training room?" % offer.from_steam_id if offer != null else ""
    _update_buttons()

func _update_buttons() -> void:
    var disabled: bool = _shown_offer == null or _joining
    accept_button.disabled = disabled
    dismiss_button.disabled = disabled

func _accept_offer() -> void:
    var confirmed: SteamInvite = _shown_offer
    _joining = true
    _update_buttons()
    var joined: GameResult = await _game.accept_invite(confirmed)
    status.text = "Joined the training room." if joined.ok else joined.message
    _joining = false
    _update_buttons()

func _dismiss_offer() -> void:
    var dismissed: GameResult = _game.dismiss_invite(_shown_offer)
    status.text = "Invitation dismissed." if dismissed.ok else dismissed.message

extends Button

@export var pause_menu: Control
@export var title_menu: Control

func _ready() -> void:
    pressed.connect(_return_to_title)

func _return_to_title() -> void:
    var game: Game = Game.for_node(self)
    if game == null:
        push_error("No game owns this pause menu.")
        return

    disabled = true
    var left: GameResult = await game.leave()
    disabled = false
    if not left.ok:
        push_error(left.message)
        return
    pause_menu.hide()
    title_menu.show()

extends Node

const LOOPBACK_ADDRESS: String = "127.0.0.1"

@export var level: PackedScene
@export var player: PackedScene

class TestTransportProvider extends GameProvider:
    func _register(bindings: GameBindings) -> void:
        var registered: int = bindings.session_transport(_make_transport)
        if registered != OK:
            push_error("Could not register the test transport.")

    func _make_transport() -> SessionTransport:
        print("Created the test transport.")
        return ENetSessionTransport.new()

func _ready() -> void:
    var provider: GameProvider = TestTransportProvider.new()
    var setup: GameConfig = Game.configure(level, player).lan().provider(provider)
    var game: Game = setup.boot(self)
    var hosted: GameResult = await game.host(LOOPBACK_ADDRESS)
    if not hosted.ok:
        push_error(hosted.message)
        return
    print("Test host ready on UDP port ", game.get_port())

extends Node

const TRAINING_ACHIEVEMENT: String = "TRAINING_COMPLETE"

@export var status: Label

var _steam: Steamworks

func _ready() -> void:
    _steam = Steamworks.boot(self)

func training_completed() -> void:
    var achievements: SteamAchievements = _steam.achievements()
    var submitted: SteamStatsSubmissionResult = achievements.unlock(TRAINING_ACHIEVEMENT)
    status.text = "Achievement sent to Steam." if submitted.ok else submitted.message
